-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Watches native waypoint changes and coordinates map refreshes.

local Shared = APR.map._helpers
local Project = Shared.Project
local SetMinimapRotation = Shared.SetMinimapRotation
local UpdateMinimapData = Shared.UpdateMinimapData

function APR.map:RefreshNativeWaypointWatch(waypointUpdated)
    local services, nav = APR.Services, APR.navigation
    local active = services and services.active
    local step = active and active.step
    local profile = APR.settings and APR.settings.profile
    if
        not (
            step
            and step._mapWaypoint
            and step.target
            and nav
            and profile
            and profile.enableAddon
            and C_Map
            and C_Map.GetUserWaypoint
        )
    then
        if self.nativeWaypointOwner then self.eventFrame:UnregisterEvent("USER_WAYPOINT_UPDATED") end
        self.nativeWaypointOwner, self.nativeWaypointMatched = nil, nil
        return
    end
    if self.nativeWaypointOwner ~= active then
        if not self.nativeWaypointOwner then self.eventFrame:RegisterEvent("USER_WAYPOINT_UPDATED") end
        self.nativeWaypointOwner, self.nativeWaypointMatched = active, nil
    elseif not waypointUpdated then
        return
    end

    local matched = self.nativeWaypointMatched
    self.nativeWaypointMatched = nil
    local marker = C_Map.GetUserWaypoint()
    if issecretvalue and issecretvalue(marker) then return end
    if marker then
        local position, mapID = marker.position, marker.uiMapID
        if issecretvalue and (issecretvalue(position) or issecretvalue(mapID)) then return end
        if not position or type(mapID) ~= "number" then return end
        local mx, my = position.x, position.y
        if issecretvalue and (issecretvalue(mx) or issecretvalue(my)) then return end
        if type(mx) ~= "number" or type(my) ~= "number" then return end
        local target = step.target
        local x, y = Project({
            Coord = step.Coord,
            uiMapID = target.uiMapID,
            instanceID = target.instanceID,
            accessKey = target.accessKey,
            floor = target.floor,
        }, mapID)
        self.nativeWaypointMatched = x and y and math.abs(mx - x) < 0.0005 and math.abs(my - y) < 0.0005
    elseif waypointUpdated and matched and WorldMapFrame:IsShown() and not nav.worldLoading then
        -- The event is synchronous. Let the map finish untracking the marker
        -- and let any in-flight navigation cleanup or marker replacement settle.
        local generation = nav.generation
        C_Timer.NewTimer(0, --[[APR_DIAG]]APRTrace("APR-Core/features/navigation/map/MapEvents.lua:65:callback#2", --[[/APR_DIAG]]function()
            local settings = APR.settings and APR.settings.profile
            if
                services.active ~= active
                or nav.generation ~= generation
                or nav.worldLoading
                or not settings
                or not settings.enableAddon
            then
                return
            end
            local current = C_Map.GetUserWaypoint()
            if (not issecretvalue or not issecretvalue(current)) and not current then
                services:Cancel()
            end
        end--[[APR_DIAG]])--[[/APR_DIAG]])
    end
end--[[APR_DIAG]]; APR.map.RefreshNativeWaypointWatch = APRTrace("APR-Core/features/navigation/map/MapEvents.lua:13:APR.map:RefreshNativeWaypointWatch#1", APR.map.RefreshNativeWaypointWatch)--[[/APR_DIAG]]

APR.map.eventFrame = CreateFrame("Frame")
for _, event in ipairs({
    "CVAR_UPDATE",
    "QUEST_LOG_UPDATE",
    "MINIMAP_UPDATE_ZOOM",
    "ZONE_CHANGED",
    "ZONE_CHANGED_INDOORS",
    "ZONE_CHANGED_NEW_AREA",
    "NEW_WMO_CHUNK",
    "PLAYER_ENTERING_WORLD",
}) do
    APR.map.eventFrame:RegisterEvent(event)
end
APR.map.eventFrame:SetScript("OnEvent", --[[APR_DIAG]]APRTrace("APR-Core/features/navigation/map/MapEvents.lua:97:callback#3", --[[/APR_DIAG]]function(_, event, ...)
    if event == "USER_WAYPOINT_UPDATED" then
        APR.map:RefreshNativeWaypointWatch(true)
        return
    end
    if
        not APR.settings.profile.enableAddon
        or not (
            APR.ActiveRoute
            or (APR.Services and APR.Services.active)
            or (APR.navigation and APR.navigation.queue and #APR.navigation.queue > 0)
            or (APR.navigationPreview and #APR.navigationPreview:GetPoints() > 0)
        )
    then
        if APR.map.pinRefreshTimer then
            APR.map.pinRefreshTimer:Cancel()
            APR.map.pinRefreshTimer = nil
        end
        APR.map:RefreshActivity()
        APR.map.pendingPinRefresh = nil
        APR.map:RemoveMapIcons()
        APR.map:RemoveMiniMapIcons()
        APR.map:RemoveMapLine()
        APR.map:RemoveMinimapLine()
        return
    end
    if event == "CVAR_UPDATE" then
        local cvar, value = ...
        if cvar == "rotateMinimap" or cvar == "ROTATE_MINIMAP" then SetMinimapRotation(value) end
    elseif event == "QUEST_LOG_UPDATE" then
        APR.map:QueueMapPins()
    elseif event == "MINIMAP_UPDATE_ZOOM" then
        UpdateMinimapData()
    else
        if APR.navigationPreview then APR.navigationPreview:InvalidateProjectionCache() end
        if APR.map.worldRenderCache then APR.map.worldRenderCache.points = nil end
        if APR.map.minimapRenderCache then APR.map.minimapRenderCache.points = nil end
        UpdateMinimapData()
        APR.map:QueueMapPins()
    end
    APR.map:RefreshActivity()
end--[[APR_DIAG]])--[[/APR_DIAG]])

APR.map._helpers = nil
